var a=`0542-shuwa`;var i=`world-0542`;var t=`OM`;var o=`western-asia`;var r=4;var s=435;var d={en:`Shuwa`,ua:`Шува`};var l={en:`A traditional dish from Oman, centered on lamb, garlic, lemon juice, banana leaf. A measured home-kitchen version organized by cooking step. Omani shuwa-inspired oven-roasted lamb wrapped in banana leaves; traditional underground pit cooking is not reproduced.`,ua:`Традиційна страва кухні країни Оман. Основні складники: ягнятина, часник, лимонний сік, банановий лист. Домашній варіант із кількостями продуктів за етапами приготування. Баранина за мотивами оманської шуви: запікається в духовці в банановому листі замість традиційної земляної печі.`};var g=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 180 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 180 хвилин.`,t:[`marinating`],m:180,i:[[`lamb`,1100,`g`],[`garlic`,6,`clove`],[`ground-cumin`,7,`g`],[`ground-cardamom`,4,`g`],[`lemon-juice`,55,`ml`],[`sunflower-oil`,65,`ml`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:10,i:[[`banana-leaf`,4,`pcs`]]},{en:`Wrap the lamb in banana leaves and foil, set in a covered roasting tray and slow-cook in the oven until tender; do not attempt an improvised underground pit.`,ua:`Загорніть баранину в бананове листя та фольгу, покладіть у закриту форму й повільно запікайте в духовці до м’якості; не облаштовуйте імпровізовану земляну піч.`,t:[`roasting`],m:240,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:5,i:[[`basmati-rice`,480,`g`]]}];var m={slug:a,id:i,country:`OM`,region:o,servings:4,minutes:435,title:d,text:l,steps:g};export{t as country,m as default,i as id,s as minutes,o as region,r as servings,a as slug,g as steps,l as text,d as title};